def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]

    r0 = min(r for r, c in pts)
    r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts)
    c1 = max(c for r, c in pts)
    out = [row[:] for row in grid]

    # Complete the rectangular outer frame.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Complete interrupted internal horizontal strokes, while preserving
    # regular parallel bars that already continue vertically.
    for r in range(r0 + 1, r1):
        cols = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
        if len(cols) < 4:
            continue
        sustained = True
        for c in cols:
            length = 1
            rr = r - 1
            while rr >= r0 and grid[rr][c] != bg:
                length += 1
                rr -= 1
            rr = r + 1
            while rr <= r1 and grid[rr][c] != bg:
                length += 1
                rr += 1
            if length < 3:
                sustained = False
                break
        if not sustained:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    return out
